android.extraProguardRules:
# Reglas de R8 para el release.
#
# El grueso de las reglas no está acá: React Native, Expo, MapLibre y Lottie
# publican sus propias "consumer rules" dentro de sus AAR y R8 las aplica solo.
# Acá va únicamente lo que esas reglas no cubren, que es lo que se rompe por
# reflexión: nombres de clase que se resuelven en tiempo de ejecución desde
# strings, y que por lo tanto R8 no ve usados desde ningún lado.
#
# Si algo revienta en release y anda en debug, casi siempre es esto: buscar el
# ClassNotFoundException / NoSuchMethodException en logcat y agregar un -keep.
# Para desactivar todo de una: android.enableMinifyInReleaseBuilds=false.

# --- React Native ---------------------------------------------------------
# Los módulos nativos se instancian por nombre desde el bridge.
-keep,includedescriptorclasses class com.facebook.react.bridge.** { *; }
-keep,includedescriptorclasses class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.jni.** { *; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }

# Hermes.
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jsi.** { *; }

# --- Expo -----------------------------------------------------------------
# expo-modules-core arma los módulos con reflexión de Kotlin: sin esto, las
# definiciones quedan sin nombre y la app no encuentra ningún módulo de Expo.
-keep class expo.modules.** { *; }
-keepclassmembers class * { @expo.modules.core.interfaces.ExpoMethod <methods>; }

# Metadatos de Kotlin, que expo-modules-core lee para resolver tipos.
-keep class kotlin.Metadata { *; }
-keepclassmembers class **$WhenMappings { <fields>; }

# --- Reanimated, gestos y pantallas ---------------------------------------
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }

# --- Red ------------------------------------------------------------------
# OkHttp referencia Conscrypt/BouncyCastle/OpenJSSE de forma opcional. No están
# en el APK y no hacen falta, pero R8 avisa igual y aborta el build.
-dontwarn org.conscrypt.**
-dontwarn org.bouncycastle.**
-dontwarn org.openjsse.**
-dontwarn okhttp3.internal.platform.**
-dontwarn javax.annotation.**

# --- Varias ---------------------------------------------------------------
# El puente de SVG mapea props por nombre.
-keep class com.horcrux.svg.** { *; }

# Deja los nombres de archivo y línea en los stack traces: sin esto, un crash
# en producción llega ofuscado y no se puede leer en logcat.
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
